import {GlobeIcon, NoteIcon, OrganizationIcon, RepoIcon} from '@primer/octicons-react'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {Dialog, Label, Text} from '@primer/react'
import {FgpScopes, type FgpMetadata, type ScopeMetadata} from '../types/fgp-metadata'
import styles from './RoleFgpsDialog.module.css'
import {testIdProps} from '@github-ui/test-id-props'
import type {Role} from '../types/role-assignments'
import {isEsm} from '../utils/role-utils'

export interface RoleFgpsDialogProps {
  role: Role
  show: boolean
  onClose: () => void
  returnFocusRef?: React.RefObject<HTMLButtonElement | null>
}

export function RoleFgpsDialog({role, show, onClose, returnFocusRef}: RoleFgpsDialogProps) {
  const isInPreview = isEsm(role)
  return (
    show && (
      <Dialog
        title={titleWithOptionalBetaLabel(role.name, isInPreview)}
        subtitle={role.description}
        onClose={onClose}
        footerButtons={[{content: 'Close', onClick: onClose}]}
        returnFocusRef={returnFocusRef}
      >
        <div className="d-flex flex-column gap-4">
          {emptyFgpMetadata(role.fgpMetadata) ? (
            <div>No permissions have been added to this role.</div>
          ) : (
            Object.values(FgpScopes).map(scope => {
              // Always include Repository scope if there's a baseRepositoryRole, even if the scope is undefined
              const isRepositoryWithBaseRole = scope === FgpScopes.Repository && role.fgpMetadata?.baseRepositoryRole

              return (
                (isRepositoryWithBaseRole || role.fgpMetadata?.[scope]) &&
                scopeSection(role.id, scope, role.fgpMetadata?.[scope] ?? {}, role.fgpMetadata?.baseRepositoryRole)
              )
            })
          )}
        </div>
      </Dialog>
    )
  )
}

function emptyFgpMetadata(fgpMetadata: FgpMetadata | undefined) {
  const noFgpMetadata = fgpMetadata === undefined || Object.keys(fgpMetadata).length === 0
  if (noFgpMetadata) {
    return true
  }

  // If baseRepositoryRole is defined, we consider the metadata to be non-empty
  if (fgpMetadata.baseRepositoryRole) {
    return false
  }

  // case of fgpMetadata having no permission categories for any scopes, even if scopes are defined
  // e.g. { 'Enterprise': {}, 'Organization': {}, 'Repository': {} }
  const noFgps = Object.values(FgpScopes).every(
    scope => fgpMetadata[scope] === undefined || Object.keys(fgpMetadata[scope]).length === 0,
  )

  return noFgps
}

// Renders a title for the role FGPs dialog, with an option for a beta label
function titleWithOptionalBetaLabel(title: string, isInPreview?: boolean) {
  return (
    <div className="d-flex gap-2">
      {title}
      {isInPreview && <BetaLabel>Preview</BetaLabel>}
    </div>
  )
}

// renders hierarchical display of: scope + icon, the categories of permissions role has within the scope, and individual permissions role has under each category
// renders nothing if there are no permissions for the scope, unless it's Repository scope with a baseRepositoryRole
function scopeSection(roleId: number, scope: string, scopeMetadata: ScopeMetadata, baseRepositoryRole?: string) {
  const showBaseRepoRole = scope === FgpScopes.Repository && baseRepositoryRole
  const noFgps = Object.keys(scopeMetadata).length === 0

  // case of scope being defined but not having any permission categories
  // e.g. 'Enterprise' = {} or 'Organization' = {}
  if (noFgps && !showBaseRepoRole) {
    return null
  }

  return (
    <div key={`${roleId}-${scope}-fgps`} className={styles.scopeInfo}>
      <div className={styles.scopeHeader}>
        <span>
          {scopeIcon(scope)}
          <span className={styles.scopeName}>{scope}</span>
        </span>
        {showBaseRepoRole && (
          <span {...testIdProps('base-repository-role')}>
            <Text size="small" className="fgColor-muted">
              Base repository role:{' '}
            </Text>
            <Label variant="accent">{baseRepositoryRole}</Label>
          </span>
        )}
      </div>
      {showBaseRepoRole && (
        <Text
          size="small"
          weight="semibold"
          className="fgColor-muted tmp-pl-4"
          {...testIdProps('base-repository-role-description')}
        >
          {`All ${baseRepositoryRole.toLowerCase()} permissions${!noFgps ? ' plus…' : ''}`}
        </Text>
      )}
      {Object.keys(scopeMetadata).map(category => (
        <div key={`${roleId}-${scope}-${category}`} className={styles.categoryInfo}>
          <span>{category}</span>
          <ul className={styles.permissionInfo}>
            {scopeMetadata[category] &&
              scopeMetadata[category].map(permission => (
                <li key={`${roleId}-${scope}-${category}-${permission}`}>
                  <span>•</span> {permission}
                </li>
              ))}
          </ul>
        </div>
      ))}
    </div>
  )
}

// will need to be updated when organization and repo permissions can be assigned
function scopeIcon(scope: string) {
  switch (scope) {
    case 'Enterprise':
      return <GlobeIcon className="color-fg-muted" />
    case 'Organization':
      return <OrganizationIcon className="color-fg-muted" />
    case 'Repository':
      return <RepoIcon className="color-fg-muted" />
    default:
      return <NoteIcon className="color-fg-muted" />
  }
}
