import type {FgpMetadata} from './fgp-metadata'

export type ActorRoleAssignment = {
  actor: Actor
  role_assignments: RoleAssignment[]
}

export type RoleAssignment = {
  role: Role
  directly_assigned: boolean
  indirect_assignments: IndirectRoleAssignmentSource[]
  org_access?: OrgAccess
}

export type Role = {
  id: number
  name: string
  description: string | null
  octicon: string
  enterpriseOwner?: {
    slug: string
    name: string
  }
  fgpMetadata?: FgpMetadata
}

export const RoleType = {
  Enterprise: 'enterprise',
  Organization: 'organization',
} as const

export type RoleType = (typeof RoleType)[keyof typeof RoleType]

export type IndirectRoleAssignmentSource = {
  team_name: string
  team_url: string
  team_avatar_url: string
  type: string
}

export type Actor = {
  id: number
  name: string
  description: string | null
  avatar_url: string
  type: ActorType
  permalink: string
}

export const ActorType = {
  User: 'User',
  EnterpriseTeam: 'BusinessTeam',
  Team: 'Team',
} as const

export type ActorType = (typeof ActorType)[keyof typeof ActorType]

export type ActorBasicMeta = {
  id: number
  name: string
  type: ActorType
}

export interface AvatarOrg {
  id: number
  displayLogin: string
  avatarURL: string
}

export interface AvatarEnterprise {
  id: number
  displayLogin: string
  avatarURL: string
}

export type OrgAccess = {
  target: OrgAccessTargetType
  selected_count?: number
  total_count?: number
  limit?: number
}

export type OrgAccessTargetType = (typeof OrgAccessTargetType)[keyof typeof OrgAccessTargetType]

export const OrgAccessTargetType = {
  AllOrgs: 'all_orgs',
  SomeOrgs: 'some_orgs',
} as const
