export const FgpScopes = {
  Enterprise: 'Enterprise',
  Organization: 'Organization',
  Repository: 'Repository',
} as const

export type FgpScopes = (typeof FgpScopes)[keyof typeof FgpScopes]

/* FgpMetadata example:
  {
    'Enterprise': { 'category1': ['permissionA', 'permissionB'], 'category2': ['permissionC'] },
    'Organization': { 'category3': ['permissionD']] },
    'Repository': { 'category4': ['permissionE', 'category5': ['permissionF'] },
    'baseRepositoryRole': 'read' // optional
  }
*/
export type FgpMetadata = {
  baseRepositoryRole?: string
} & {
  [key in FgpScopes]: ScopeMetadata
}

export type ScopeMetadata = {
  [key: string]: string[]
}
